	// their tokens (we expect that UnmarshalCaddyfile should be able to
	// handle more than one segment); otherwise, we'd overwrite other
	// instances of the matcher in this set
	tokensByMatcherName := make(map[string][]caddyfile.Token)
	for nesting := d.Nesting(); d.NextArg() || d.NextBlock(nesting); {
		matcherName := d.Val()
		tokensByMatcherName[matcherName] = append(tokensByMatcherName[matcherName], d.NextSegment()...)
	}
	for matcherName, tokens := range tokensByMatcherName {
		err := st.makeMatcherModule(definitionName, matcherName, tokens)
		if err != nil {
			return err
		}
	}
	return nil
}

// expressionMatcherTokens synthesizes the implicit "expression" matcher
// name token in front of a quoted CEL expression.
func (st *ServerType) expressionMatcherTokens(d *caddyfile.Dispenser) []caddyfile.Token {
	if st.namedMatchers == nil {
